      if (onlyFolderChildren.length === 1 && fileChildren.length === 0) {
        const collapsed = this.collapseNode(onlyFolderChildren[0])
        return {
          ...collapsed,
          name: `${node.name}/${collapsed.name}`,
          path: collapsed.path
        }
      }
      return node
    },

    // Recursively collect all leaf file paths under a node
    collectFilePaths(node) {
      if (!node.isFolder) return [node.path]
      return (node.children || []).flatMap(child => this.collectFilePaths(child))
    },

    // Emit bulk select/deselect for all files in this folder
    toggleFolderSelection() {
      const paths = this.folderFilePaths
      this.$emit('toggle-select-many', { paths, select: !this.folderAllSelected })
    },

    copyPath() {
      this.$ui.copyTextToClipboard(this.displayNode.path)
    }
  }
}
</script>
```

### Summary of changes

**`KanbanTreeNode.vue`**:
- **Folder checkbox** moved to appear **before** the folder icon (after the chevron), so selection is visually grouped with folder identity
- **File action icons**: a hidden-by-default (revealed on `group-hover`) row of action buttons appears on each file row:
  - **Copy** (`fa-regular fa-copy`) — calls `this.$ui.copyTextToClipboard(displayNode.path)` to copy the full file path to clipboard
- Used Tailwind `group` / `group-hover:opacity-100` pattern so actions don't clutter the tree until hovered

